'use strict';

const fs = require('node:fs');
const path = require('node:path');

/**
 * Reads .concord/WORK_STATE.json (regenerated by Concord after every write,
 * or on demand with `concord export markdown`) and normalizes it into a
 * snapshot: { generatedAt, tasks: Map, agents: Map }.
 * Returns null when the file is missing or unreadable.
 */
function readSnapshot(concordDir, log = () => {}) {
  const file = path.join(concordDir, 'WORK_STATE.json');
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      log('warn', `${file} not found. Is Concord set up in this repository? (run "concord setup")`);
    } else {
      log('error', `Cannot read ${file}: ${err.message}`);
    }
    return null;
  }
  try {
    return normalize(JSON.parse(raw));
  } catch (err) {
    // The file may be caught mid-write; the next poll will retry.
    log('warn', `Cannot parse ${file}: ${err.message}`);
    return null;
  }
}

function normalize(state) {
  const tasks = new Map();
  for (const t of Array.isArray(state.tasks) ? state.tasks : []) {
    if (!t || typeof t.task_id !== 'string') continue;
    tasks.set(t.task_id, {
      id: t.task_id,
      title: t.title || t.task_id,
      status: t.status,
      agentId: t.agent_id || null,
      assignedAgentId: t.assigned_agent_id || null,
      updatedAt: t.updated_at || null,
      leaseExpiresAt: t.lease_expires_at || null,
      expectedFiles: Array.isArray(t.expected_files) ? t.expected_files : [],
      modules: Array.isArray(t.modules) ? t.modules : [],
    });
  }
  const agents = new Map();
  for (const a of Array.isArray(state.presence) ? state.presence : []) {
    if (!a || typeof a.agent_id !== 'string') continue;
    agents.set(a.agent_id, { id: a.agent_id, kind: a.kind || null, lastSeen: a.last_seen || null });
  }
  return { generatedAt: state.generated_at || null, tasks, agents };
}

module.exports = { readSnapshot, normalize };
